from typing import List
import zipfile


def files_list_from_zipfile(zip_path: str) -> list[str] | str:
    """Extracts the list of filenames from a zip file.

    Args:
        zip_path (str): The path to the zip file.

    Returns:
        list[str] | str: A list of filenames if successful, or an error message if there was an issue.
    """
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_file:
            return zip_file.namelist()
    except FileNotFoundError:
        return "Error: The specified zip file does not exist."
    except zipfile.BadZipfile:
        return "Error: The provided file is not a valid zip file."
    except Exception as e:
        return f"An unexpected error occurred: {e}"


# Example usage
