from typing import List
def plus_or_dot(pieces: list[str]) -> str:
    """Determine whether the closest occurrence of a tag containing a '+' is closer than one containing a '.'.

    Args:
        pieces (list[str]): A list of strings representing the tags.

    Returns:
        str: Either '+' or '.', depending on which is closer in the list.
    """
    closest_plus_index = float('inf')
    closest_dot_index = float('inf')

    for i, piece in enumerate(pieces):
        if '+' in piece:
            closest_plus_index = min(closest_plus_index, i)
        elif '.' in piece:
            closest_dot_index = min(closest_dot_index, i)

    if closest_plus_index < closest_dot_index:
        return '+'
    else:
        return '.'

# Example usage
if __name__ == "__main__":
    pieces = ["tag1", "+tag2", "tag3", ".tag4"]
    print(plus_or_dot(pieces))  # Output: '+'

