from typing import List, Dict

def _dictsum(dicts: List[Dict[str, int]]) -> Dict[str, int]:
    """
    Sum the values of common keys across multiple dictionaries.

    Args:
        dicts (List[Dict[str, int]]): A list of dictionaries containing string keys and integer values.

    Returns:
        Dict[str, int]: A dictionary with summed values for each key present in the input dictionaries.
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

# Example usage
